import React, { useState } from "react";
import axios from "axios";

const SearchBar = ({ setHomes }) => {
  const [searchParams, setSearchParams] = useState({
    location: "",
    startDate: "",
    endDate: "",
    maxPersons: "",
    houseType: "",
  });
  const [error, setError] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setSearchParams((prev) => ({ ...prev, [name]: value }));
  };

  const handleSearch = async () => {
    if (!searchParams.location) {
      setError("Please enter a location to search.");
      return;
    }

    try {
      const params = new URLSearchParams();
      if (searchParams.location)
        params.append("location", searchParams.location.toLowerCase()); // Case-insensitive
      if (searchParams.startDate)
        params.append("startDate", searchParams.startDate);
      if (searchParams.endDate) params.append("endDate", searchParams.endDate);
      if (searchParams.maxPersons)
        params.append("maxPersons", searchParams.maxPersons);
      if (searchParams.houseType)
        params.append("houseType", searchParams.houseType);

      const response = await axios.get(
        `http://localhost:5000/search?${params.toString()}`
      );
      setHomes(response.data);
      setError(null);
      console.log(`Search results: ${response.data.length} houses`);
    } catch (err) {
      console.error("Search failed:", err);
      setError("Failed to search. Please try again.");
    }
  };

  return (
    <div
      style={{
        padding: "1rem",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: "0.5rem",
      }}
    >
      <div
        style={{
          display: "flex",
          gap: "1rem",
          flexWrap: "wrap",
          justifyContent: "center",
          backgroundColor: "rgba(0, 0, 0, 0.5)",
          padding: "1rem",
          borderRadius: "0.3rem",
        }}
      >
        <input
          type="text"
          name="location"
          value={searchParams.location}
          onChange={handleChange}
          placeholder="Search by location..."
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
            width: "200px",
            backgroundColor: "white",
          }}
        />
        <input
          type="date"
          name="startDate"
          value={searchParams.startDate}
          onChange={handleChange}
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
            backgroundColor: "white",
          }}
        />
        <input
          type="date"
          name="endDate"
          value={searchParams.endDate}
          onChange={handleChange}
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
            backgroundColor: "white",
          }}
        />
        <select
          name="maxPersons"
          value={searchParams.maxPersons}
          onChange={handleChange}
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
            backgroundColor: "white",
          }}
        >
          <option value="">Max Persons</option>
          <option value="1">1</option>
          <option value="2">2</option>
          <option value="3">3</option>
          <option value="4">4+</option>
        </select>
        <select
          name="houseType"
          value={searchParams.houseType}
          onChange={handleChange}
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
            backgroundColor: "white",
          }}
        >
          <option value="">House Type</option>
          <option value="Apartment">Apartment</option>
          <option value="Villa">Villa</option>
          <option value="House">House</option>
        </select>
        <button
          onClick={handleSearch}
          style={{
            padding: "0.5rem 1rem",
            backgroundColor: "#3b82f6",
            color: "white",
            borderRadius: "0.3rem",
            border: "none",
            cursor: "pointer",
          }}
        >
          Search
        </button>
      </div>
      {error && (
        <div
          style={{
            color: "#ff5555",
            fontSize: "1.2rem",
            marginTop: "0.5rem",
            backgroundColor: "rgba(44, 44, 68, 0.8)",
            padding: "0.5rem",
            borderRadius: "0.3rem",
          }}
        >
          {error}
        </div>
      )}
      {!error && searchParams.location && (
        <div
          style={{ color: "#d1d5db", fontSize: "1.2rem", marginTop: "0.5rem" }}
        >
          No homes found in that area.
        </div>
      )}
    </div>
  );
};

export default SearchBar;
